package phala

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

type composeHashVector struct {
	Name      string         `json:"name"`
	Input     map[string]any `json:"input"`
	Canonical string         `json:"canonical"`
	Hash      string         `json:"hash"`
}

// The vectors are shared with the JS and Python SDKs and were generated by the
// Phala Cloud backend.
func loadComposeHashVectors(t *testing.T) []composeHashVector {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "test-vectors", "app_compose_hash.json"))
	if err != nil {
		t.Fatal(err)
	}
	var file struct {
		Cases []composeHashVector `json:"cases"`
	}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.UseNumber()
	if err := decoder.Decode(&file); err != nil {
		t.Fatal(err)
	}
	return file.Cases
}

func TestGetComposeHashFromMapMatchesBackend(t *testing.T) {
	for _, vector := range loadComposeHashVectors(t) {
		t.Run(vector.Name, func(t *testing.T) {
			canonical, err := DumpAppComposeFromMap(vector.Input)
			if err != nil {
				t.Fatal(err)
			}
			if canonical != vector.Canonical {
				t.Fatalf("canonical mismatch\n got: %s\nwant: %s", canonical, vector.Canonical)
			}
			got, err := GetComposeHashFromMap(vector.Input)
			if err != nil {
				t.Fatal(err)
			}
			if got != vector.Hash {
				t.Fatalf("hash mismatch: got %s, want %s", got, vector.Hash)
			}
		})
	}
}

func TestGetComposeHashStructDoesNotEscapeHTML(t *testing.T) {
	// Go's encoding/json escapes <, > and & by default; the backend does not.
	compose := AppCompose{Runner: "docker-compose", Name: "html<&>", DockerComposeFile: "a<b && c>d"}
	canonical, err := DumpAppComposeFromMap(map[string]any{
		"runner": "docker-compose", "name": "html<&>", "docker_compose_file": "a<b && c>d",
	})
	if err != nil {
		t.Fatal(err)
	}
	want := `{"docker_compose_file":"a<b && c>d","name":"html<&>","runner":"docker-compose"}`
	if canonical != want {
		t.Fatalf("got %s, want %s", canonical, want)
	}
	got, err := GetComposeHash(compose, true)
	if err != nil {
		t.Fatal(err)
	}
	wantHash, err := GetComposeHashFromMap(map[string]any{
		"runner": "docker-compose", "name": "html<&>", "docker_compose_file": "a<b && c>d",
	})
	if err != nil {
		t.Fatal(err)
	}
	if got != wantHash {
		t.Fatalf("struct hash %s != map hash %s", got, wantHash)
	}
}
